def transform(grid):
    from collections import Counter

    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    background = counts.most_common(1)[0][0]

    # Locate the full-width, non-background floor.
    floor_row = None
    for r, row in enumerate(g):
        if len(set(row)) == 1 and row[0] != background:
            floor_row = r
    if floor_row is None:
        return g

    obj = [(r, c, g[r][c])
           for r in range(floor_row) for c in range(w)
           if g[r][c] != background]
    if not obj:
        return g

    # Drop the object until its lowest cell is just above the floor.
    drop = min(floor_row - 1 - r for r, c, color in obj)
    for r, c, color in obj:
        g[r][c] = background
    for r, c, color in obj:
        g[r + drop][c] = color

    top = min(r + drop for r, c, color in obj)
    if top > 0:
        g[top - 1] = [8] * w
    return g
